<script lang="ts">
 import {onMount} from 'svelte';
 import {datevRowKey,parseDatevMapping,serializeDatevMapping,type DatevRow} from '#lib/client/datev-mapping.ts';
 import Icon from './Icon.svelte';
 let {value=$bindable(),id}:{value?:any;id:string}=$props();
 let rows:DatevRow[]=$state([]),error=$state('');
 const kinds=[{value:'normal',label:'Reguläre Rechnung'},{value:'advance',label:'Anzahlung'},{value:'progress',label:'Abschlag'},{value:'partial',label:'Teilleistung'},{value:'final',label:'Schlussrechnung'},{value:'correction',label:'Berichtigung'},{value:'credit',label:'Gutschrift'},{value:'supplier_invoice',label:'Lieferantenbeleg'},{value:'payment_incoming',label:'Zahlungseingang'},{value:'payment_outgoing',label:'Zahlungsausgang'}];
 const categories=[{value:'S',label:'Reguläre Umsatzsteuer (S)'},{value:'Z',label:'Nullsteuersatz (Z)'},{value:'E',label:'Steuerbefreit (E)'},{value:'AE',label:'Steuerschuld beim Empfänger (AE)'},{value:'K',label:'Innergemeinschaftliche Lieferung (K)'},{value:'G',label:'Ausfuhrlieferung (G)'},{value:'O',label:'Nicht steuerbarer Umsatz (O)'}];
 onMount(()=>{try{if(value===undefined||value===null||value==='')value='{}';rows=parseDatevMapping(value).map(row=>({...row,id:crypto.randomUUID()}));}catch(cause){error=cause instanceof Error?cause.message:'Die bisherige Zuordnung ist nicht lesbar.';}});
 function change(){
  error='';for(const row of rows){let message='';try{const key=datevRowKey(row);if(key&&rows.filter(other=>{try{return datevRowKey(other)===key;}catch{return false;}}).length>1)message='Diesen Beleg- und Steuerfall nur einmal zuordnen.';}catch(cause){message=cause instanceof Error?cause.message:'Steuerfall prüfen.';}const control=document.getElementById(`${id}-${row.id}-kind`) as HTMLSelectElement|null;control?.setCustomValidity(message);if(message)error=message;}
  if(error)return;try{value=serializeDatevMapping(rows);}catch(cause){error=cause instanceof Error?cause.message:'Zuordnung prüfen.';}
 }
 function chooseKind(row:DatevRow,kind:string){row.kind=kind;if(kind.startsWith('payment_')){row.mode='kind';row.category='';row.rate='';}else row.mode='exact';change();}
 function add(){rows=[...rows,{id:crypto.randomUUID(),kind:'',category:'',rate:'',account:'',counter:'',tax:'',mode:'exact'}];}
</script>
<fieldset class="datev-mapping"><legend>Freigegebene Kontenzuordnung</legend><p class="field-help">Übernehmen Sie jeden Beleg- und Steuerfall aus dem bestätigten Verfahren Ihrer Kanzlei. Unterschiedliche Steuersätze sowie Anzahlung, Abschlag und Schlussrechnung brauchen eigene Kontenzuordnungen. Konten werden nicht vorausgewählt.</p>
{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}
{#each rows as row,index}<div class="datev-row">
 <div class="datev-row-heading"><h4>Zuordnung {index+1}</h4><button class="icon-button" type="button" aria-label={`Kontenzuordnung ${index+1} entfernen`} onclick={()=>{rows=rows.filter(item=>item.id!==row.id);change();}}><Icon name="trash" size={16}/></button></div>
 {#if row.mode==='legacy'}<p class="field-help legacy">Übernommene allgemeine Zuordnung: {row.category}. Diese ersetzt keine getrennte Zuordnung für mehrere Steuergruppen oder Anzahlungs-/Schlussrechnungsfälle.</p><button class="text-link legacy" type="button" onclick={()=>{row.mode='exact';row.kind='';row.rate='';change();}}>Mit bestätigter Belegart und Steuersatz konkretisieren</button>{/if}
 <div class="field"><label for={`${id}-${row.id}-kind`}>Belegart *</label><select id={`${id}-${row.id}-kind`} value={row.kind} onchange={event=>chooseKind(row,event.currentTarget.value)} required={row.mode!=='legacy'}><option value="">{row.mode==='legacy'?'Allgemeine Bestandszuordnung':'Bitte auswählen'}</option>{#if row.kind&&!kinds.some(kind=>kind.value===row.kind)}<option value={row.kind}>{row.kind} · gespeicherter Fall</option>{/if}{#each kinds as kind}<option value={kind.value}>{kind.label}</option>{/each}</select></div>
 {#if row.mode==='exact'}<div class="field"><label for={`${id}-${row.id}-category`}>Steuerfall *</label><select id={`${id}-${row.id}-category`} value={row.category} onchange={event=>{row.category=event.currentTarget.value;change();}} required><option value="">Laut Kanzleiverfahren</option>{#each categories as category}<option value={category.value}>{category.label}</option>{/each}</select></div><div class="field"><label for={`${id}-${row.id}-rate`}>Steuersatz · % *</label><input id={`${id}-${row.id}-rate`} value={row.rate} oninput={event=>{row.rate=event.currentTarget.value;change();}} inputmode="decimal" pattern="[0-9]+([,.][0-9]+)?" required placeholder="Zum Beispiel 19 oder 7"/></div>{:else if row.mode==='kind'&&!row.kind.startsWith('payment_')}<p class="field-help broad-mapping">Gespeicherte Zuordnung ohne Steueraufteilung. Nur bei einer eindeutigen einzelnen Steuergruppe verwendbar. <button class="text-link" type="button" onclick={()=>{row.mode='exact';change();}}>Steuerfall ergänzen</button></p>{/if}
 <div class="field"><label for={`${id}-${row.id}-account`}>Konto *</label><input id={`${id}-${row.id}-account`} value={row.account} oninput={event=>{row.account=event.currentTarget.value;change();}} inputmode="numeric" pattern={'[0-9]{4,9}'} required/></div><div class="field"><label for={`${id}-${row.id}-counter`}>Gegenkonto *</label><input id={`${id}-${row.id}-counter`} value={row.counter} oninput={event=>{row.counter=event.currentTarget.value;change();}} inputmode="numeric" pattern={'[0-9]{4,9}'} required/></div><div class="field"><label for={`${id}-${row.id}-tax`}>BU-Schlüssel</label><input id={`${id}-${row.id}-tax`} value={row.tax} oninput={event=>{row.tax=event.currentTarget.value;change();}} inputmode="numeric" pattern={'[0-9]{0,4}'}/><span class="field-help">Nur laut bestätigtem Kanzleiverfahren leer lassen.</span></div>
</div>{/each}
<button class="btn mt" type="button" onclick={add}><Icon name="plus" size={15}/>Kontenzuordnung hinzufügen</button>{#if !rows.length}<p class="field-help mt">Noch keine Zuordnung hinterlegt. Ein DATEV-Export benötigt das vollständige und fachlich freigegebene Verfahren.</p>{/if}<p class="field-help mt">Die Eingabe allein erteilt keine fachliche Verfahrensfreigabe. Halten Sie den bestätigten Kontenplan und den Nachweis der Kanzlei bereit.</p><details class="mt"><summary class="field-help">Technische Zuordnung ansehen</summary><pre class="json-preview mt">{typeof value==='string'?value:JSON.stringify(value,null,2)}</pre></details></fieldset>
<style>.datev-mapping{padding:0;border:0;margin:0;min-width:0}.datev-mapping legend{font-size:14px;font-weight:500;margin-bottom:10px}.datev-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;border:1px solid var(--line);background:var(--wash);border-radius:7px;padding:20px;margin-top:20px}.datev-row-heading{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between}.datev-row-heading h4{font-size:13px;font-weight:550}.datev-row input,.datev-row select{min-width:0;width:100%}.datev-row .legacy,.broad-mapping{grid-column:1/-1}.datev-row .field-help{font-size:12px}.datev-row .icon-button{width:36px;height:36px}@media(max-width:1100px){.datev-row{grid-template-columns:repeat(2,minmax(0,1fr))}.datev-row>.field:nth-of-type(2){grid-column:1/-1}}@media(max-width:760px){.datev-row{grid-template-columns:1fr;padding:18px}.datev-row>.field{grid-column:1/-1}.datev-row input,.datev-row select{font-size:16px;min-height:48px}.datev-row .icon-button{width:48px;height:48px}}</style>
